const app=document.getElementById('app');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=(n,c='RUB')=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:c,maximumFractionDigits:2}).format(n);const date=x=>new Date(x).toLocaleString('ru-RU');let data;let saved={};try{saved=JSON.parse(localStorage.getItem('checkpoint')||'{}')}catch{}let state={platform:'Все',regions:['US','PL','TR','JP','BR'],wishlist:[],...saved};let selectedStore='';let query='';let sorting='discount';let saleOnly=false;const persist=()=>{try{localStorage.setItem('checkpoint',JSON.stringify(state))}catch{}document.getElementById('count').textContent=state.wishlist.length};const toggle=id=>{state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];persist()};const region=id=>data.regions.find(x=>x[0]===id)?.[1]||id;
const offers=(g,store=state.platform)=>g.offers.filter(o=>state.regions.includes(o.region)&&(store==='Все'||o.store===store)).sort((a,b)=>a.rub-b.rub);const art=g=>`<img class="cover" src="${esc(g.image)}" alt="${esc(g.name)}" loading="lazy" referrerpolicy="no-referrer">`;
function home(){const wish=location.hash==='#wishlist';app.innerHTML=`<div class="top"><div><div class="eyebrow">ИГРЫ ПО ВАШЕЙ ЦЕНЕ</div><h1>${wish?'Мои игры':'Скидки, которых вы ждали.'}</h1><p>Сравнивайте цены официальных магазинов в разных регионах.</p><a class="telegram-note" href="#account">↗ Уведомления о скидках — бесплатно в Telegram <span>Бот скоро</span></a></div></div><div class="filters" id="header-filters"><div class="tools">${['Все','Nintendo','PS5','Xbox','Steam'].map(p=>`<button data-platform="${p}" class="${state.platform===p?'active':''}">${p}</button>`).join('')}<label><input id="sale" type="checkbox"> Только со скидкой</label><select id="sort" aria-label="Сортировка"><option value="discount">Сначала скидки</option><option value="price">Сначала дешевле</option><option value="name">По названию</option></select></div><details class="regions"><summary>Регионы · <span id="region-count">${state.regions.length}</span></summary><div class="region-menu"><input id="region-search" placeholder="Найти страну…" aria-label="Поиск страны">${data.regions.map(([id,n])=>`<label><input class="country-check" type="checkbox" value="${id}" ${state.regions.includes(id)?'checked':''}>${n}</label>`).join('')}<div class="region-actions"><button id="all-regions">Все</button><button id="clear-regions">Сбросить</button><button id="close-regions">Готово</button></div></div></details></div><div class="section-head"><h2>${wish?'Список желаемого':'Каталог и скидки'}</h2><span id="results" class="muted"></span></div><div class="grid" id="cards"></div><details class="panel coverage"><summary>Источники и покрытие регионов</summary><p>Steam: ${data.games.filter(g=>g.offers.some(o=>o.store==='Steam')).length} игры. Для Stray и Deep Rock Galactic пока получены цены только США; для остальных — пяти регионов. Nintendo: 3 игры, США. PS5 и Xbox: Hades, США. Показываем только полученные предложения.</p><p>Обновлено: ${date(data.fetchedAt)}. Это сохранённый снимок; автоматическое обновление ещё не включено.</p><p>Пересчёт по <a href="${data.fxSource}" target="_blank" rel="noopener">курсам ЦБ</a> от ${esc(data.fxDate)}. Итоговая сумма покупки может отличаться. Валюта предложения определяется магазином, а не страной.</p></details>`;
const filterbar=document.getElementById('header-filters');document.getElementById('filter-host').replaceChildren(filterbar);document.getElementById('sort').value=sorting;document.getElementById('sale').checked=saleOnly;
function draw(){sorting=document.getElementById('sort').value;saleOnly=document.getElementById('sale').checked;let list=data.games.map(g=>({g,o:offers(g)})).filter(({g,o})=>o.length&&(!wish||state.wishlist.includes(g.id)));if(document.getElementById('sale').checked)list=list.filter(({o})=>o.some(x=>x.discount>0));const sort=document.getElementById('sort').value;list.sort((a,b)=>sort==='price'?a.o[0].rub-b.o[0].rub:sort==='name'?a.g.name.localeCompare(b.g.name):Math.max(...b.o.map(x=>x.discount||0))-Math.max(...a.o.map(x=>x.discount||0)));document.getElementById('results').textContent=list.length+' игр';document.getElementById('cards').innerHTML=list.map(({g,o})=>card(g,o)).join('')||'<div class="empty">Нет подтверждённых предложений для выбранных фильтров. Попробуйте США или другую платформу.</div>';app.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{toggle(b.dataset.save);draw()})}
document.getElementById('sort').onchange=draw;document.getElementById('sale').onchange=draw;document.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{state.platform=b.dataset.platform;persist();document.querySelectorAll('[data-platform]').forEach(x=>x.classList.toggle('active',x===b));draw()});document.querySelectorAll('.country-check').forEach(c=>c.onchange=()=>{state.regions=[...document.querySelectorAll('.country-check:checked')].map(x=>x.value);persist();document.getElementById('region-count').textContent=state.regions.length;draw()});document.getElementById('all-regions').onclick=()=>{state.regions=data.regions.map(x=>x[0]);persist();home()};document.getElementById('clear-regions').onclick=()=>{state.regions=[];persist();home();document.querySelector('.regions').open=true};document.getElementById('close-regions').onclick=()=>document.querySelector('.regions').open=false;document.getElementById('region-search').oninput=e=>document.querySelectorAll('.region-menu label').forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(e.target.value.toLowerCase()));draw()}
function detail(id){document.getElementById('filter-host').replaceChildren();const g=data.games.find(x=>x.id===id);if(!g){app.innerHTML='<h1>Игра не найдена</h1><a href="#">В каталог</a>';return}const stores=[...new Set(g.offers.map(o=>o.store))];if(!stores.includes(selectedStore))selectedStore=stores.includes(state.platform)?state.platform:stores[0];const os=offers(g,selectedStore);app.innerHTML=`<a href="#" class="back">← Все игры</a><div class="detail-top"><div><div class="eyebrow">${esc(g.genre)}</div><h1>${esc(g.name)}</h1><p>${esc(g.description)}</p><p class="meta">${esc(g.developer)} · ${esc(g.release)}</p><a class="meta" href="${esc(g.metadataSource)}" target="_blank" rel="noopener">Описание и изображение: официальный магазин ↗</a><div class="tools" style="margin-top:20px"><select id="store" aria-label="Магазин">${stores.map(s=>`<option ${selectedStore===s?'selected':''}>${s}</option>`).join('')}</select><span class="meta">Базовая игра · стандартное издание</span><button id="save" class="primary">${state.wishlist.includes(id)?'✓ В желаемом':'+ Желаемое'}</button></div></div><div class="detail-cover">${art(g)}</div></div><section class="panel"><div class="section-head"><h2>Цены по регионам</h2><a href="#">Настроить регионы ↗</a></div><p class="meta">${esc(selectedStore)} · курсы ЦБ от ${esc(data.fxDate)} · ₽ и $ — расчётные значения</p><div class="table-wrap"><table><thead><tr><th>Регион</th><th>Рубли</th><th>Доллары</th><th>Цена магазина</th><th>Проверено</th><th></th></tr></thead><tbody>${os.map(o=>`<tr><td>${esc(region(o.region))}</td><td class="rub-price">≈ ${money(o.rub)}</td><td>≈ ${money(o.usd,'USD')}</td><td>${money(o.amount,o.currency)}${o.discount>0?` <span class="badge">−${o.discount}%</span>`:''}</td><td class="meta">${date(o.checkedAt)}</td><td><a href="${esc(o.url)}" target="_blank" rel="noopener">В магазин ↗</a></td></tr>`).join('')||'<tr><td colspan="6">Нет проверенных цен для выбранных регионов.</td></tr>'}</tbody></table></div></section><div class="cols"><section class="panel"><h2>История цены</h2><p>Наблюдение началось ${date(data.fetchedAt)}. График появится после накопления данных.</p><p class="meta">Сохраняем отдельные наблюдения для магазина, региона и валюты. Старые цены не восстанавливаем предположениями.</p></section><section class="panel"><h2>Желаемая цена</h2><label for="target">Сумма в рублях</label><input id="target" class="target" type="number" min="0" step="0.01" placeholder="Например, 1500"><button id="alert" class="primary">Сохранить цель</button><p class="meta">Уведомления бесплатные и будут приходить в Telegram-боте. Пока цель сохраняется только в этом браузере.</p><div id="alert-status" class="status" aria-live="polite"></div></section></div>`;document.getElementById('store').onchange=e=>{selectedStore=e.target.value;detail(id)};document.getElementById('save').onclick=()=>{toggle(id);detail(id)};document.getElementById('alert').onclick=()=>{let v=document.getElementById('target');if(v.value===''||!v.checkValidity()){document.getElementById('alert-status').textContent='Введите сумму от 0.';return}state.targets=state.targets||{};state.targets[id]={amount:Number(v.value),currency:'RUB',platform:selectedStore,regions:[...state.regions]};if(!state.wishlist.includes(id))state.wishlist.push(id);persist();document.getElementById('alert-status').textContent='Сохранено: '+money(Number(v.value))}}

function card(g,o){const b=o[0];return `<article class="game"><a href="#game/${g.id}"><div class="art">${art(g)}${b.discount>0?`<small>−${b.discount}%</small>`:''}</div><div class="info"><h3 title="${esc(g.name)}">${esc(g.name)}</h3><div class="price-line"><strong>≈ ${money(b.rub)}</strong><span>≈ ${money(b.usd,'USD')}</span></div><div class="store-line"><span>${esc(b.store)} · ${esc(region(b.region))}</span><b>${money(b.amount,b.currency)}</b></div></div></a><div class="bottom"><a href="#game/${g.id}">Сравнить · ${o.length}</a><button data-save="${g.id}" aria-label="Отслеживать ${esc(g.name)}" aria-pressed="${state.wishlist.includes(g.id)}">${state.wishlist.includes(g.id)?'✓':'+'}</button></div></article>`}
const dialog=document.getElementById('search-dialog');let opener;
function closeSearch(){if(dialog.open){dialog.close();document.body.classList.remove('search-open');opener?.focus()}}
function openSearch(){if(!data)return;opener=document.activeElement;dialog.showModal();document.body.classList.add('search-open');document.getElementById('live-search').value=query;renderSearch();document.getElementById('live-search').focus()}
function renderSearch(){query=document.getElementById('live-search').value;const q=query.trim().toLocaleLowerCase();const matches=data.games.filter(g=>g.name.toLocaleLowerCase().includes(q));document.getElementById('search-caption').textContent=q?`Найдено: ${matches.length}`:'Начните вводить название игры';document.getElementById('search-cards').innerHTML=(q?matches:data.games.slice(0,6)).map(g=>card(g,[...g.offers].sort((a,b)=>a.rub-b.rub))).join('')||'<div class="empty">Ничего не найдено. Попробуйте другое название.</div>';dialog.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{toggle(b.dataset.save);renderSearch();if(document.getElementById('cards'))home()});dialog.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeSearch))}
document.getElementById('search-open').onclick=openSearch;document.getElementById('live-search').oninput=renderSearch;document.getElementById('search-close').onclick=closeSearch;dialog.addEventListener('click',e=>{if(e.target===dialog)closeSearch()});dialog.addEventListener('cancel',e=>{e.preventDefault();closeSearch()});
const media=matchMedia('(prefers-color-scheme: dark)');function applyTheme(){let pref=state.theme||'system';document.documentElement.dataset.theme=pref==='system'?(media.matches?'dark':'light'):pref;document.getElementById('theme').value=pref}document.getElementById('theme').onchange=e=>{state.theme=e.target.value;persist();applyTheme()};media.addEventListener('change',applyTheme);applyTheme();
function account(){document.getElementById('filter-host').replaceChildren();let targets=Object.entries(state.targets||{}).filter(([id])=>data.games.some(g=>g.id===id));app.innerHTML=`<div class="account-title"><div class="eyebrow">ВАШ CHECKPOINT</div><h1>Личный кабинет</h1><p>Желаемое и настройки уведомлений в одном месте.</p></div><div class="account-grid"><section class="panel"><h2>Профиль</h2><p class="meta">Локальный профиль: данные хранятся в этом браузере. Вход и синхронизация появятся после подключения базы данных.</p><form id="profile-form"><label for="profile-name">Как к вам обращаться</label><input id="profile-name" maxlength="60" value="${esc(state.profileName||'')}" placeholder="Ваше имя"><button class="primary">Сохранить профиль</button><div id="profile-status" class="status" aria-live="polite"></div></form><a href="#wishlist">Мой список желаемого · ${state.wishlist.length} →</a></section><section class="panel telegram-panel"><span class="free-label">БЕСПЛАТНО</span><h2>Скидка пришла — бот сообщит</h2><p>Все уведомления будут приходить в Telegram-боте. Отслеживание скидок бесплатно.</p><button disabled>Telegram-бот скоро</button><p class="meta">Подключение бота пока недоступно. Вы уже можете сохранить игры и целевые цены.</p><label class="notification-choice"><input id="notify-discount" type="checkbox" ${state.notifyDiscount!==false?'checked':''}> Любая скидка на игры из желаемого</label><label class="notification-choice"><input id="notify-target" type="checkbox" ${state.notifyTarget!==false?'checked':''}> Цена достигла моего порога</label><div id="notification-status" class="status" aria-live="polite"></div></section></div><section class="panel"><h2>Мои ценовые цели</h2><div class="target-list">${targets.map(([id,t])=>{const g=data.games.find(g=>g.id===id);return `<div class="target-row"><a href="#game/${id}">${esc(g.name)}<small>${esc(t.platform)} · ${(t.regions||[]).map(region).map(esc).join(', ')}</small></a><strong>${money(t.amount,t.currency||'RUB')}</strong><button data-delete="${id}" aria-label="Удалить цель ${esc(g.name)}">Удалить</button></div>`}).join('')||'<p>Откройте страницу игры и задайте желаемую цену — она появится здесь.</p>'}</div></section>`;document.getElementById('profile-form').onsubmit=e=>{e.preventDefault();state.profileName=document.getElementById('profile-name').value.trim();persist();document.getElementById('profile-status').textContent='Профиль сохранён в этом браузере'};['discount','target'].forEach(k=>document.getElementById('notify-'+k).onchange=e=>{state[k==='discount'?'notifyDiscount':'notifyTarget']=e.target.checked;persist();document.getElementById('notification-status').textContent='Настройки сохранены. Отправка начнётся после подключения бота.'});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{delete state.targets[b.dataset.delete];persist();account()})}
function route(){if(!data)return;closeSearch();if(location.hash==='#account')account();else if(location.hash.startsWith('#game/'))detail(location.hash.slice(6));else home();persist();window.scrollTo(0,0)}document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=document.querySelector('.regions');if(d)d.open=false}});document.addEventListener('click',e=>{const d=document.querySelector('.regions');if(d&&!d.contains(e.target))d.open=false});window.addEventListener('hashchange',route);app.innerHTML='<p>Загружаем каталог…</p>';fetch('catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{data=x;route()}).catch(()=>app.innerHTML='<h2>Каталог временно недоступен</h2><p>Обновите страницу позже.</p>');
